"use client";
import { useId, useState } from 'react';
export interface ChartDatum { label: string; values: Record<string, number | null> }
export interface ChartSeries { key: string; label: string; color?: string }
export interface ChartProps {
  title: string; description?: string; data: ChartDatum[]; series: ChartSeries[]; unit?: string;
  height?: number; loading?: boolean;
}
const palette=['var(--cs-brand)','#0ea5e9','#f97316','#22c55e','#a855f7'];
export function LineChart(props:ChartProps) {return <Chart {...props} kind="line"/>;}
export function BarChart(props:ChartProps) {return <Chart {...props} kind="bar"/>;}
function Chart({title,description,data,series,unit='',height=280,loading=false,kind}:ChartProps&{kind:'line'|'bar'}) {
  const id=useId();const [active,setActive]=useState<number | undefined>(undefined);const [hidden,setHidden]=useState<string[]>([]);
  const visible=series.filter(item=>!hidden.includes(item.key));
  const values=data.flatMap(row=>visible.map(item=>row.values[item.key])).filter((n):n is number=>typeof n==='number'&&Number.isFinite(n));
  const low=Math.min(0,...values);const high=Math.max(0,...values);const span=high-low||1;const min=low<0?low-span*.1:0;const max=high>0?high+span*.1:1;
  const width=640,top=20,left=56,right=16,bottom=40,plotHeight=220,plotWidth=width-left-right;
  const y=(value:number)=>top+plotHeight-(value-min)/(max-min)*plotHeight;
  const step=plotWidth/Math.max(1,data.length);const x=(i:number)=>left+step*(i+.5);
  const color=(item:ChartSeries)=>item.color??palette[series.indexOf(item)%palette.length];
  const selected=active===undefined?undefined:data[active];
  const format=(n:number)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2,notation:Math.abs(n)>=10000?'compact':'standard'}).format(n);
  return <figure className="cs-chart" aria-labelledby={`${id}-title`}>
    <figcaption><strong id={`${id}-title`}>{title}</strong>{description&&<p>{description}</p>}</figcaption>
    <div className="cs-chart-legend" role="group" aria-label={`${title} 数据序列`}>{series.map(item=><button key={item.key} type="button" aria-pressed={!hidden.includes(item.key)} onClick={()=>setHidden(current=>current.includes(item.key)?current.filter(key=>key!==item.key):[...current,item.key])}><span style={{background:color(item)}}/>{item.label}</button>)}</div>
    {loading?<div className="cs-chart-empty" style={{height}} role="status">正在加载图表…</div>:!data.length||!series.length?<div className="cs-chart-empty" style={{height}}>暂无图表数据</div>:<>
      <div className="cs-chart-plot" onMouseLeave={()=>setActive(undefined)}>
        <svg viewBox={`0 0 ${width} ${top+plotHeight+bottom}`} width="100%" height={Math.max(180,height)} role="img" aria-label={`${title}，${kind==='line'?'折线图':'柱状图'}，${data.length} 组数据；详细数值见下方数据表`}>
          {[0,1,2,3,4].map(i=>{const value=min+(max-min)*i/4;const yy=y(value);return <g key={i}><line x1={left} x2={width-right} y1={yy} y2={yy} stroke="var(--cs-border)" strokeDasharray="3 3"/><text x={left-10} y={yy+4} textAnchor="end" fill="var(--cs-muted)" fontSize="11">{format(value)}</text></g>;})}
          {min<0&&<line x1={left} x2={width-right} y1={y(0)} y2={y(0)} stroke="var(--cs-muted)"/>}
          {kind==='line'&&visible.map(item=>{let path='';let connected=false;data.forEach((row,i)=>{const n=row.values[item.key];if(typeof n!=='number'||!Number.isFinite(n)){connected=false;return;}path+=`${connected?'L':'M'}${x(i)},${y(n)} `;connected=true;});return <path key={item.key} d={path} fill="none" stroke={color(item)} strokeWidth="2" strokeLinejoin="round"/>;})}
          {data.map((row,i)=><g key={`${row.label}-${i}`}>
            {(data.length<=10||i%Math.ceil(data.length/8)===0)&&<text x={x(i)} y={top+plotHeight+24} textAnchor="middle" fill="var(--cs-muted)" fontSize="11">{row.label.length>10?row.label.slice(0,9)+'…':row.label}</text>}
            {visible.map((item,j)=>{const n=row.values[item.key];if(typeof n!=='number'||!Number.isFinite(n))return null;const barWidth=Math.min(36,step*.7/Math.max(1,visible.length));return kind==='bar'?<rect key={item.key} x={x(i)-visible.length*barWidth/2+j*barWidth} y={Math.min(y(0),y(n))} width={Math.max(1,barWidth-3)} height={Math.max(1,Math.abs(y(n)-y(0)))} rx="3" fill={color(item)} opacity={active===undefined||active===i?1:.55}/>:<circle key={item.key} cx={x(i)} cy={y(n)} r={active===i?5:3} fill="var(--cs-surface)" stroke={color(item)} strokeWidth="2"/>;})}
            <rect x={left+step*i} y={top} width={step} height={plotHeight} fill="transparent" tabIndex={0} role="button" aria-label={`${row.label}：${visible.map(item=>`${item.label} ${typeof row.values[item.key]==='number'?row.values[item.key]:'无数据'} ${unit}`).join('，')}`} onMouseEnter={()=>setActive(i)} onFocus={()=>setActive(i)} onBlur={()=>setActive(undefined)} onKeyDown={event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();const next=event.key==='ArrowRight'?event.currentTarget.parentElement?.nextElementSibling:event.currentTarget.parentElement?.previousElementSibling;next?.querySelector<SVGRectElement>('[role="button"]')?.focus();}}}/>
          </g>)}
        </svg>
      </div>
      <div className="cs-chart-readout" aria-live="polite">{selected?<><strong>{selected.label}</strong>{visible.map(item=><span key={item.key}>{item.label}：{typeof selected.values[item.key]==='number'?format(selected.values[item.key]!):'—'} {unit}</span>)}</>:<span>悬浮或使用 Tab、方向键查看数值{unit?` · 单位 ${unit}`:''}</span>}</div>
      <details className="cs-chart-data"><summary>查看数据表</summary><div className="cs-table-scroll"><table className="cs-table"><caption className="cs-sr-only">{title}原始数据</caption><thead><tr><th>项目</th>{series.map(item=><th key={item.key}>{item.label}{unit?` (${unit})`:''}</th>)}</tr></thead><tbody>{data.map((row,i)=><tr key={i}><th scope="row">{row.label}</th>{series.map(item=><td key={item.key}>{typeof row.values[item.key]==='number'&&Number.isFinite(row.values[item.key])?format(row.values[item.key]!):'—'}</td>)}</tr>)}</tbody></table></div></details>
    </>}
  </figure>;
}

"use client";
import { useEffect, useRef, useState } from 'react';
import { HexColorPicker } from 'react-colorful';
import { Tabs, TabsList, TabsTrigger, TabsContent } from './navigation';
export interface ColorFill {
  mode: 'solid' | 'gradient' | 'image';
  color: string;
  opacity: number;
  endColor: string;
  angle: number;
  imageUrl?: string;
}
export interface ColorPickerProps {
  value?: ColorFill;
  defaultValue?: Partial<ColorFill>;
  onChange?: (fill: ColorFill) => void;
  disabled?: boolean;
  onClose?: () => void;
}
const defaults: ColorFill = { mode:'solid',color:'#170057',opacity:100,endColor:'#a855f7',angle:90 };
const validHex = (text: string) => /^#[0-9a-f]{6}$/i.test(text);
export function colorFillBackground(fill: ColorFill): string {
  const color=validHex(fill.color)?fill.color:defaults.color;
  const end=validHex(fill.endColor)?fill.endColor:defaults.endColor;
  return fill.mode==='gradient' ? `linear-gradient(${Number.isFinite(fill.angle)?fill.angle:90}deg, ${color}, ${end})` : color;
}
export function ColorPicker({value,defaultValue,onChange,disabled=false,onClose}:ColorPickerProps) {
  const [internal,setInternal]=useState<ColorFill>({...defaults,...defaultValue});
  const fill=value??internal;
  const [draft,setDraft]=useState(fill.color);
  const [error,setError]=useState('');
  const [message,setMessage]=useState('');
  const [saved,setSaved]=useState(['#16a34a','#2563eb','#4f46e5','#9333ea','#db2777','#dc2626','#ea580c','#170057']);
  const localImage=useRef<string | undefined>(undefined);
  useEffect(()=>{setDraft(fill.color);},[fill.color]);
  useEffect(()=>()=>{if(localImage.current)URL.revokeObjectURL(localImage.current);},[]);
  function update(patch:Partial<ColorFill>) { if(disabled)return;const next={...fill,...patch};setInternal(next);onChange?.(next);setError(''); }
  async function eyedrop() {
    const ctor=(window as unknown as {EyeDropper?:new()=>{open:()=>Promise<{sRGBHex:string}>}}).EyeDropper;
    if(!ctor){setMessage('此浏览器不支持屏幕取色，请使用色板或 Hex 输入。');return;}
    try { const result=await new ctor().open();update({color:result.sRGBHex}); } catch {setMessage('已取消取色。');}
  }
  return <div className="cs-color-picker">
    {onClose && <button type="button" className="cs-color-close" aria-label="关闭颜色选择器" onClick={onClose}>×</button>}
    <fieldset disabled={disabled} className="cs-color-fieldset">
      <legend className="cs-sr-only">填充颜色</legend>
      <Tabs value={fill.mode} onValueChange={mode=>update({mode:mode as ColorFill['mode']})}>
        <TabsList aria-label="填充类型"><TabsTrigger value="solid" disabled={disabled}>Solid</TabsTrigger><TabsTrigger value="gradient" disabled={disabled}>Gradient</TabsTrigger><TabsTrigger value="image" disabled={disabled}>Image</TabsTrigger></TabsList>
        <TabsContent value="solid"><HexColorPicker color={validHex(fill.color)?fill.color:defaults.color} onChange={color=>update({color})} aria-label="选择纯色" /></TabsContent>
        <TabsContent value="gradient"><div className="cs-color-gradient-preview" style={{background:colorFillBackground(fill)}} /><div className="cs-color-gradient-inputs"><label>起始色<input type="color" aria-label="渐变起始色" value={fill.color} onChange={e=>update({color:e.target.value})} /></label><label>结束色<input type="color" aria-label="渐变结束色" value={fill.endColor} onChange={e=>update({endColor:e.target.value})} /></label><label>角度<input type="number" aria-label="渐变角度" min="0" max="360" value={fill.angle} onChange={e=>update({angle:Math.max(0,Math.min(360,Number(e.target.value)))})} /></label></div></TabsContent>
        <TabsContent value="image"><div className="cs-color-image-preview">{fill.imageUrl?<img src={fill.imageUrl} alt="填充图片预览" onError={()=>setError('图片无法显示，请重新选择。')} />:<span>选择一张图片作为填充</span>}</div><label className="cs-field">图片文件<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>10*1024*1024){setError('请选择不超过 10 MB 的 PNG、JPG、WebP 或 GIF。');return;}if(localImage.current)URL.revokeObjectURL(localImage.current);localImage.current=URL.createObjectURL(file);update({imageUrl:localImage.current});}} /></label><p className="cs-help">仅在本地预览，最多 10 MB；持久化图片由消费项目处理。</p></TabsContent>
      </Tabs>
      <div className="cs-color-opacity"><button type="button" aria-label="屏幕取色" onClick={()=>void eyedrop()} disabled={disabled || fill.mode==='image'}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m15 4 5 5M4 20l3-1L20 6a2 2 0 0 0-3-3L4 16Z" /></svg></button><label>透明度 {fill.opacity}%<input type="range" aria-label="透明度" min="0" max="100" value={fill.opacity} onChange={e=>update({opacity:Number(e.target.value)})} /></label></div>
      {fill.mode!=='image' && <div className="cs-color-hex-row"><span>Hex</span><span className="cs-color-dot" style={{background:fill.color}} /><input aria-label="Hex 颜色" value={draft} aria-invalid={!!error} onChange={e=>{setDraft(e.target.value);if(validHex(e.target.value))update({color:e.target.value});}} onBlur={()=>{if(!validHex(draft))setError('请输入完整的六位 Hex 色值，例如 #170057。');}} /><label><input type="number" aria-label="透明度百分比" min="0" max="100" value={fill.opacity} onChange={e=>update({opacity:Math.max(0,Math.min(100,Number(e.target.value)))})} />%</label></div>}
      {error && <p role="alert" className="cs-error">{error}</p>}
      <div className="cs-color-saved-heading"><strong>Saved</strong><button type="button" disabled={fill.mode==='image'} onClick={()=>{if(validHex(fill.color)){setSaved(current=>Array.from(new Set([...current,fill.color])).slice(-16));setMessage('当前颜色已加入本次会话色板。');}}}>＋ Add</button></div>
      <div className="cs-color-swatches" role="group" aria-label="保存的颜色">{saved.map(color=><button key={color} type="button" aria-label={`选择 ${color}`} aria-pressed={fill.color.toLowerCase()===color.toLowerCase()} style={{background:color}} onClick={()=>update({color})} />)}</div>
      <span className="cs-help" role="status">{message}</span>
    </fieldset>
  </div>;
}

"use client";
import { useState, type ReactNode } from 'react';
import { Command } from 'cmdk';
import * as Dialog from '@radix-ui/react-dialog';
export interface CommandMenuItem {
  id: string;
  label: string;
  description?: string;
  icon?: ReactNode;
  shortcut?: string;
  keywords?: string[];
  disabled?: boolean;
  onSelect?: () => void;
}
export interface CommandMenuGroup { id: string; label: string; items: CommandMenuItem[] }
export interface CommandMenuProps {
  groups: CommandMenuGroup[];
  title?: string;
  placeholder?: string;
  emptyText?: string;
  trigger?: ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  onSelect?: (id: string) => void;
}
export function CommandMenu({groups,title='命令菜单',placeholder='搜索命令或页面…',emptyText='没有匹配的命令',trigger,open,onOpenChange,onSelect}:CommandMenuProps) {
  const [internal,setInternal]=useState(false);
  const [query,setQuery]=useState('');
  const isOpen=open??internal;
  const modal=trigger!==undefined||open!==undefined;
  const setOpen=(next:boolean)=>{setInternal(next);onOpenChange?.(next);if(!next)setQuery('');};
  const content=<Command className="cs-command-menu" label={title} loop>
    <div className="cs-command-menu-search"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/></svg><Command.Input value={query} onValueChange={setQuery} placeholder={placeholder} aria-label="搜索命令" />{modal&&<kbd>Esc</kbd>}</div>
    <Command.List className="cs-command-menu-list">
      <Command.Empty className="cs-command-menu-empty">{emptyText}</Command.Empty>
      {groups.map(group=><Command.Group key={group.id} heading={group.label} className="cs-command-menu-group">{group.items.map(item=><Command.Item key={item.id} value={item.id} keywords={[item.label,...(item.keywords??[])]} disabled={item.disabled} className="cs-command-menu-item" onSelect={()=>{item.onSelect?.();onSelect?.(item.id);if(modal)setOpen(false);}}>
        {item.icon&&<span className="cs-command-menu-icon" aria-hidden="true">{item.icon}</span>}
        <span className="cs-command-menu-label"><span>{item.label}</span>{item.description&&<small>{item.description}</small>}</span>
        {item.shortcut&&<kbd>{item.shortcut}</kbd>}
      </Command.Item>)}</Command.Group>)}
    </Command.List>
    <div className="cs-command-menu-footer"><span>↑ ↓ 选择</span><span>↵ 执行</span>{modal&&<span>Esc 关闭</span>}</div>
  </Command>;
  if(!modal)return content;
  return <Dialog.Root open={isOpen} onOpenChange={setOpen}>{trigger&&<Dialog.Trigger asChild>{trigger}</Dialog.Trigger>}<Dialog.Portal><Dialog.Overlay className="cs-dialog-overlay" /><Dialog.Content className="cs-command-menu-dialog" aria-describedby={undefined}><Dialog.Title className="cs-sr-only">{title}</Dialog.Title>{content}</Dialog.Content></Dialog.Portal></Dialog.Root>;
}

"use client";
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Button, EmptyState, Input } from "./index";
import { Checkbox } from "./forms";
import { Pagination } from "./navigation";
export interface DataColumn<T> {
  id: string;
  header: string;
  accessor: (row: T) => string | number;
  cell?: (row: T) => ReactNode;
  sortable?: boolean;
}
export interface DataTableProps<T> {
  data: T[];
  columns: DataColumn<T>[];
  getRowId: (row: T) => string;
  caption: string;
  pageSize?: number;
  searchPlaceholder?: string;
  selectable?: boolean;
  onSelectionChange?: (ids: string[]) => void;
  emptyTitle?: string;
}
export function DataTable<T>({
  data,
  columns,
  getRowId,
  caption,
  pageSize = 5,
  searchPlaceholder = "搜索所有列…",
  selectable = false,
  onSelectionChange,
  emptyTitle = "没有匹配记录",
}: DataTableProps<T>) {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState<{ id: string; direction: "asc" | "desc" }>();
  const [selected, setSelected] = useState<string[]>([]);
  const size = Math.max(1, Math.floor(pageSize));
  const rows = useMemo(() => {
    const filtered = data.filter((row) =>
      columns.some((column) =>
        String(column.accessor(row))
          .toLocaleLowerCase()
          .includes(query.toLocaleLowerCase()),
      ),
    );
    if (!sort) return filtered;
    const column = columns.find((c) => c.id === sort.id);
    return column
      ? [...filtered].sort((a, b) => {
          const av = column.accessor(a),
            bv = column.accessor(b);
          const order =
            typeof av === "number" && typeof bv === "number"
              ? av - bv
              : String(av).localeCompare(String(bv), undefined, {
                  numeric: true,
                });
          return sort.direction === "asc" ? order : -order;
        })
      : filtered;
  }, [data, columns, query, sort]);
  const pageCount = Math.max(1, Math.ceil(rows.length / size));
  const currentPage = Math.min(page, pageCount);
  const visible = rows.slice((currentPage - 1) * size, currentPage * size);
  const ids = visible.map(getRowId);
  const checked = ids.length > 0 && ids.every((id) => selected.includes(id));
  const mixed = ids.some((id) => selected.includes(id));
  const select = (next: string[]) => {
    setSelected(next);
    onSelectionChange?.(next);
  };
  useEffect(() => {
    const available = new Set(data.map(getRowId));
    const next = selected.filter((id) => available.has(id));
    if (next.length !== selected.length) {
      setSelected(next);
      onSelectionChange?.(next);
    }
  }, [data, getRowId, selected, onSelectionChange]);
  return (
    <div className="cs-data-table">
      <div className="cs-table-toolbar">
        <Input
          label="搜索记录"
          placeholder={searchPlaceholder}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setPage(1);
          }}
        />
        <span className="cs-help" role="status">
          {rows.length} 条记录{selectable && ` · 已选 ${selected.length} 条`}
        </span>
      </div>
      {rows.length ? (
        <div className="cs-table-scroll">
          <table className="cs-table">
            <caption className="cs-sr-only">{caption}</caption>
            <thead>
              <tr>
                {selectable && (
                  <th scope="col">
                    <Checkbox
                      label={<span className="cs-sr-only">选择当前页</span>}
                      checked={checked ? true : mixed ? "indeterminate" : false}
                      onCheckedChange={(value) =>
                        select(
                          value === true
                            ? Array.from(new Set([...selected, ...ids]))
                            : selected.filter((id) => !ids.includes(id)),
                        )
                      }
                    />
                  </th>
                )}
                {columns.map((column) => (
                  <th
                    key={column.id}
                    scope="col"
                    aria-sort={
                      sort?.id === column.id
                        ? sort.direction === "asc"
                          ? "ascending"
                          : "descending"
                        : column.sortable
                          ? "none"
                          : undefined
                    }
                  >
                    {column.sortable ? (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() =>
                          setSort({
                            id: column.id,
                            direction:
                              sort?.id === column.id && sort.direction === "asc"
                                ? "desc"
                                : "asc",
                          })
                        }
                      >
                        {column.header}
                        <svg className="cs-sort-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                          {sort?.id !== column.id ? <><path d="M8 19V5m-4 4 4-4 4 4" /><path d="M16 5v14m-4-4 4 4 4-4" /></> : sort.direction === "asc" ? <path d="M12 19V5m-6 6 6-6 6 6" /> : <path d="M12 5v14m-6-6 6 6 6-6" />}
                        </svg>
                      </Button>
                    ) : (
                      column.header
                    )}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {visible.map((row) => (
                <tr
                  key={getRowId(row)}
                  data-selected={selected.includes(getRowId(row)) || undefined}
                >
                  {selectable && (
                    <td>
                      <Checkbox
                        label={
                          <span className="cs-sr-only">
                            选择记录 {getRowId(row)}
                          </span>
                        }
                        checked={selected.includes(getRowId(row))}
                        onCheckedChange={(value) =>
                          select(
                            value === true
                              ? [...selected, getRowId(row)]
                              : selected.filter((id) => id !== getRowId(row)),
                          )
                        }
                      />
                    </td>
                  )}
                  {columns.map((column) => (
                    <td key={column.id}>
                      {column.cell?.(row) ?? column.accessor(row)}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <EmptyState
          title={emptyTitle}
          description="请调整搜索词或检查数据来源。"
        />
      )}
      <div className="cs-table-footer">
        <span className="cs-help">
          第 {currentPage} / {pageCount} 页
        </span>
        <Pagination
          page={currentPage}
          pageCount={pageCount}
          onPageChange={setPage}
        />
      </div>
    </div>
  );
}

"use client";
import { useId, useRef, useState } from 'react';
import * as Popover from '@radix-ui/react-popover';
export interface DatePickerProps {
  label: string; value?: string; defaultValue?: string; onChange?: (value:string)=>void;
  min?: string; max?: string; disabled?: boolean; error?: string; placeholder?: string;
}
function parse(value?:string) { if(!value||!/^\d{4}-\d{2}-\d{2}$/.test(value))return undefined;const [y,m,d]=value.split('-').map(Number);const date=new Date(y,m-1,d,12);return date.getFullYear()===y&&date.getMonth()===m-1&&date.getDate()===d?date:undefined; }
function iso(date:Date) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`; }
export function DatePicker({label,value,defaultValue='',onChange,min,max,disabled,error,placeholder='选择日期'}:DatePickerProps) {
  const [internal,setInternal]=useState(defaultValue);const selected=value??internal;
  const today=iso(new Date());const initial=parse(selected)??new Date();
  const [month,setMonth]=useState(new Date(initial.getFullYear(),initial.getMonth(),1,12));
  const [open,setOpen]=useState(false);const id=useId();const grid=useRef<HTMLDivElement>(null);const focusDate=useRef<string | undefined>(undefined);
