    return <li key={step.id} data-state={state} data-disabled={step.disabled||undefined}>{onStepChange?<button type="button" className="cs-step-content" aria-current={step.id===currentStep?'step':undefined} disabled={step.disabled} onClick={()=>onStepChange(step.id)}>{content}</button>:<div className="cs-step-content" aria-current={step.id===currentStep?'step':undefined}>{content}</div>}</li>;
  })}</ol></nav>;
}

