        onError={event=>{setState('error');onError?.(event);}}
        onLoadedData={event=>{setState('ready');onLoadedData?.(event);}}
        onWaiting={event=>{setState('loading');onWaiting?.(event);}}
        onPlaying={event=>{setState('ready');onPlaying?.(event);}}>
        {captions.map(track=><track key={track.src} kind="captions" {...track} />)}
        当前浏览器不支持视频播放。
      </video> : <div className="cs-video-message"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="m10 8 6 4-6 4Z"/></svg><strong>尚未选择视频</strong><span>提供视频地址或在示例中选择本地文件。</span></div>}
      {available && !playing && <button className="cs-video-center-play" type="button" aria-label="播放视频" onClick={()=>void toggle()}>{icon('play')}</button>}
      {available && <div className="cs-video-controls" role="group" aria-label="视频控制">
        <button type="button" aria-label={playing?'暂停':'播放'} onClick={()=>void toggle()}>{icon(playing?'pause':'play')}</button>
        <button type="button" aria-label={muted?'取消静音':'静音'} onClick={()=>{if(video.current)video.current.muted=!video.current.muted;}}>{icon('volume')}</button>
        <input className="cs-video-volume" type="range" aria-label="音量" min="0" max="1" step="0.05" value={muted?0:volume} onChange={e=>{if(video.current){video.current.volume=Number(e.target.value);video.current.muted=false;}}} />
        <span className="cs-video-time">{format(time)}</span>
        <input className="cs-video-progress" type="range" aria-label="播放进度" min="0" max={duration || 1} step="0.1" value={time} disabled={!duration} onChange={e=>{if(video.current)video.current.currentTime=Number(e.target.value);}} />
        <span className="cs-video-time">-{format(Math.max(0,duration-time))}</span>
        <Menu.Root>
          <Menu.Trigger className="cs-video-speed" aria-label="播放速度">{speed}×<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="m6 9 6 6 6-6" /></svg></Menu.Trigger>
          <Menu.Content className="cs-video-speed-menu" side="top" align="end" sideOffset={8} collisionPadding={8}>
            <Menu.RadioGroup value={speed} onValueChange={value=>{setSpeed(value);if(video.current)video.current.playbackRate=Number(value);}} aria-label="播放速度">
              {['0.5','0.75','1','1.25','1.5','2'].map(rate=><Menu.RadioItem className="cs-video-speed-option" key={rate} value={rate}>{rate}×<Menu.ItemIndicator aria-hidden="true">✓</Menu.ItemIndicator></Menu.RadioItem>)}
            </Menu.RadioGroup>
          </Menu.Content>
        </Menu.Root>
        {captions.length>0 && <button type="button" aria-label="字幕" aria-pressed={cc} onClick={()=>{const next=!cc;setCc(next);if(video.current)Array.from(video.current.textTracks).forEach((track,i)=>{track.mode=next&&i===0?'showing':'disabled';});}}>CC</button>}
        <button type="button" aria-label="切换全屏" onClick={()=>void fullscreen()}>{icon('full')}</button>
      </div>}
      {src && state==='loading' && <div className="cs-video-status" role="status">正在缓冲…</div>}
      {src && state==='error' && <div className="cs-video-message cs-video-error" role="alert"><strong>视频无法播放</strong><span>请检查地址、文件格式或网络连接。</span><button type="button" className="cs-button cs-button--secondary" onClick={()=>{setState('loading');video.current?.load();}}>重试</button></div>}
    </div>
    <figcaption className="cs-sr-only">{title}</figcaption>
    {!available && <select className="cs-sr-only" aria-label="播放速度" disabled value="1" onChange={()=>{}}><option value="1">1×</option></select>}
  </figure>;
}

/* Derived brand ramp; 900 is the verified CRYSOUND master color. */
:root {
  --cs-brand-50: #f0ecf8;
  --cs-brand-100: #e4dcf2;
  --cs-brand-200: #cbbbe5;
  --cs-brand-300: #af95d5;
  --cs-brand-400: #916ac1;
  --cs-brand-500: #7446a9;
  --cs-brand-600: #5c2d8e;
  --cs-brand-700: #451d76;
  --cs-brand-800: #301875;
  --cs-brand-900: #170057;
  --cs-brand-950: #0d0033;
}
/* Slate scale supplied by the user for typography. */
:root {
  --cs-slate-50: #f8fafc;
  --cs-slate-100: #f1f5f9;
  --cs-slate-200: #e2e8f0;
  --cs-slate-300: #cbd5e1;
  --cs-slate-400: #94a3b8;
  --cs-slate-500: #64748b;
  --cs-slate-600: #475569;
  --cs-slate-700: #334155;
  --cs-slate-800: #1e293b;
  --cs-slate-900: #0f172a;
  --cs-slate-950: #020617;
}
/* Brand and radius traced to Figma; system font and Slate text selected by CRYSOUND. */
:root,
[data-theme="light"] {
  color-scheme: light;
  --cs-brand: #170057;
  --cs-brand-hover: #301875;
  --cs-on-brand: #fff;
  --cs-bg: #f9f9f9;
  --cs-surface: #fff;
  --cs-subtle: #f6f6fc;
  --cs-text: var(--cs-slate-700);
  --cs-text-heading: var(--cs-slate-900);
  --cs-text-secondary: var(--cs-slate-700);
  --cs-text-disabled: var(--cs-slate-400);
  --cs-muted: var(--cs-slate-500);
  --cs-border: #d6d6d6;
  --cs-switch-on: #22c55e;
  --cs-success: #22c55e;
  --cs-success-fg: #176541;
  --cs-success-bg: #e9f6ed;
  --cs-warning: #f97316;
  --cs-warning-fg: #9a3412;
  --cs-warning-bg: #fff3dd;
  --cs-danger: #dc2626;
  --cs-danger-fg: #b42318;
  --cs-accent: #a855f7;
  --cs-danger-bg: #fff0ee;
  --cs-focus: #61528d;
  --cs-radius: 4px;
  --cs-font:
    "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", sans-serif;
  --cs-space-1: 4px;
  --cs-space-2: 8px;
  --cs-space-3: 12px;
  --cs-space-4: 16px;
  --cs-space-6: 24px;
  --cs-space-8: 32px;
  --cs-control-height: 40px;
  --cs-font-size: 14px;
  --cs-shadow: 0 8px 32px #17005714;
}
[data-theme="dark"] {
  color-scheme: dark;
  --cs-brand: #c4b5fd;
  --cs-brand-hover: #ddd6fe;
  --cs-on-brand: #170057;
  --cs-bg: #111019;
  --cs-surface: #1c1928;
  --cs-subtle: #292438;
  --cs-text: var(--cs-slate-200);
  --cs-text-heading: var(--cs-slate-50);
  --cs-text-secondary: var(--cs-slate-200);
  --cs-text-disabled: var(--cs-slate-600);
  --cs-muted: var(--cs-slate-400);
  --cs-border: #514961;
  --cs-success: #8be0ae;
  --cs-success-fg: #8be0ae;
  --cs-success-bg: #193a28;
  --cs-warning: #ffcf85;
  --cs-warning-fg: #ffcf85;
  --cs-warning-bg: #3d2e17;
  --cs-danger: #ffb4a9;
  --cs-danger-fg: #ffb4a9;
  --cs-accent: #c084fc;
  --cs-danger-bg: #42241e;
  --cs-focus: #c4b5fd;
}
[data-density="compact"] {
  --cs-control-height: 32px;
  --cs-font-size: 13px;
}
/* Example customer theme; the accessible foreground is part of the override. */
[data-customer="ocean"] {
  --cs-brand: #1857b6;
  --cs-brand-hover: #12458f;
  --cs-on-brand: #fff;
  --cs-focus: #1857b6;
}
[data-customer="ocean"][data-theme="dark"] {
  --cs-brand: #95baff;
  --cs-brand-hover: #b6cfff;
  --cs-on-brand: #102348;
  --cs-focus: #95baff;
}

/* OpenTest software surface profile; preserve the shared brand. */
[data-context="software"][data-theme="light"] {
  --cs-bg: #e2e8f0;
  --cs-surface: #fff;
  --cs-subtle: #f1f5f9;
  --cs-text: var(--cs-slate-700);
  --cs-text-heading: var(--cs-slate-900);
  --cs-muted: var(--cs-slate-500);
  --cs-border: #cbd5e1;
}

